const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Helper function to mask clouds from Landsat 4/5/7 SR data.
function maskL457sr(image) {
  const qa = image.select('pixel_qa');
  const cloud = qa.bitwiseAnd(1 << 5).or(qa.bitwiseAnd(1 << 7));
  const mask2 = image.mask().reduce(ee.Reducer.min());
  return image.updateMask(cloud.not()).updateMask(mask2);
}

// Helper function to mask clouds from Landsat 8 SR data.
function maskL8sr(image) {
  const qa = image.select('QA_PIXEL');
  const cloud = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4));
  const mask2 = image.mask().reduce(ee.Reducer.min());
  return image.updateMask(cloud.not()).updateMask(mask2);
}

// Function to calculate the built-up area for a given year and sensor.
function calculateBuiltUpArea(collection, aoi, reducerScale) {
  const image = collection.median();

  // Calculate NDBI: (SWIR1 - NIR) / (SWIR1 + NIR)
  const nir = image.select('NIR');
  const swir1 = image.select('SWIR1');
  const ndbi = image.normalizedDifference(['SWIR1', 'NIR']).rename('NDBI');

  // Built-up areas are where NDBI > 0
  const builtUp = ndbi.gt(0);
  const areaImage = builtUp.multiply(ee.Image.pixelArea()).divide(1e6); // Area in sq km

  const stats = areaImage.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: reducerScale,
    maxPixels: 1e10
  });

  const pixelCount = builtUp.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: aoi,
      scale: reducerScale,
      maxPixels: 1e10
  }).get(ndbi.bandNames().get(0));

  return [stats.get(builtUp.bandNames().get(0)), pixelCount];
}

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Polygon([
      [
        [31.25, 30.10],
        [31.45, 30.10],
        [31.45, 29.95],
        [31.25, 29.95],
        [31.25, 30.10]
      ]
  ]);
  const reducerScale = 1000;

  // 2. Data Acquisition & Processing for 1984
  let area1984 = null;
  let pixels1984 = 0;
  const collection1984_L5 = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
    .filterBounds(aoi)
    .filterDate('1984-07-01', '1984-07-31')
    .map(maskL457sr)
    .select(['B4', 'B5'], ['NIR', 'SWIR1']);

  const count1984 = collection1984_L5.size().getInfo();
  if (count1984 > 0) {
    const [area, pixels] = calculateBuiltUpArea(collection1984_L5, aoi, reducerScale);
    area1984 = area.getInfo();
    pixels1984 = pixels.getInfo();
  } else {
      console.log("No Landsat 5 images found for July 1984.");
      console.log("A"); // The question is about an increase. If 1984 is 0, any value in 2019 is an increase.
      return;
  }

  if (pixels1984 === 0) {
      console.log("No valid pixels found for July 1984 after cloud masking.");
      console.log("C2");
      return;
  }
  console.log(`1984 (L5) Built-up Area (km^2): ${area1984 ? area1984.toFixed(2) : 'N/A'}`);

  // 3. Data Acquisition & Processing for 2019
  let area2019 = null;
  let pixels2019 = 0;
  const collection2019_L8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(aoi)
    .filterDate('2019-09-01', '2019-09-30')
    .map(maskL8sr)
    .select(['SR_B5', 'SR_B6'], ['NIR', 'SWIR1']);

  const count2019 = collection2019_L8.size().getInfo();
  if (count2019 === 0) {
    console.log("No Landsat 8 images found for September 2019.");
    console.log("C1");
    return;
  }

  const [area, pixels] = calculateBuiltUpArea(collection2019_L8, aoi, reducerScale);
  area2019 = area.getInfo();
  pixels2019 = pixels.getInfo();

  if (pixels2019 === 0) {
      console.log("No valid pixels found for September 2019 after cloud masking.");
      console.log("C2");
      return;
  }
  console.log(`2019 (L8) Built-up Area (km^2): ${area2019 ? area2019.toFixed(2) : 'N/A'}`);

  // 4. Validation & Final Answer
  if (area1984 === null || area2019 === null) {
      console.log("Calculation failed for one or both periods.");
      console.log("C3");
      return;
  }

  const increase = area2019 > area1984;
  console.log(`Change in built-up area (km^2): ${(area2019 - area1984).toFixed(2)}`);

  if (increase) {
      console.log("A");
  } else {
      console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred:", err);
    console.log("D");
});
